pub fn sysroot_unpack(packed: &str) -> Option<Vec<(String, String)>> {
    let mut files: Vec<(String, String)> = vec![];
    let pieces: Vec<&str> = packed.split("\n").collect::<Vec<_>>();
    for at in 0..pieces.len() as i64 {
        let line: String = match ((unsafe { nikaia_std::proven::add::<i64>(at, 1) }) as usize) < pieces.len() {
            true => format!("{}\n", *unsafe { nikaia_std::proven::read(&pieces, (at) as usize) }),
            false => nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&pieces, (at) as usize) }).to_string()),
        };
        if line.is_empty() { continue; }
        if line.starts_with(AsRef::<str>::as_ref(SYSROOT_PACKED)) { files.push((nikaia_std::block::Text::from(nikaia_std::index::or(line.strip_prefix(AsRef::<str>::as_ref(SYSROOT_PACKED)), || "").trim_end().to_string()), String::from(""))); } else {
            if files.is_empty() { return None; }
            let last = unsafe { nikaia_std::proven::sub::<i64>(files.len() as i64, 1) };
            files[nikaia_std::index::at(last)].1.push_str(&line);
        }
    }
    if files.is_empty() { return None; }
    Some(files)
}

pub async fn sysroot_lowered_key<H: SysrootHost>(compiler: Option<&str>, what: &str, files: &[fs::Path], host: &H) -> Option<String> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let given = match compiler { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut read: Vec<u8> = vec![];
    sysroot_ended(&mut read, "nikaia-lower-std-v1");
    sysroot_ended(&mut read, given);
    sysroot_ended(&mut read, what);
    for file in files.iter() {
        let source = __keep_frame.put(match fs::read(file, &fs::Root::Anywhere).await {
            Ok(value) => value,
            Err(_error) => { return None; },
        });
        let name = match nikaia_std::fs::path::file_name(&(file)) { Some(__nikaia_value) => __nikaia_value, None => return None };
        sysroot_part(&mut read, &nikaia_std::fs::path::text_of(&(name)));
        sysroot_length(&mut read, source.len() as i64);
        for b in source.iter().copied() { read.push(b); }
    }
    Some(hash::sha256_hex(&read))
}

pub async fn sysroot_lowered_get<H: SysrootHost>(root: &std::path::Path, cached: bool, key: Option<String>, host: &H) -> Option<String> {
    let entry = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(match key { Some(__nikaia_value) => __nikaia_value, None => return None })));
    if !cached { return None; }
    let rust = match fs::read_to_string(&nikaia_std::fs::path::join(&(entry), std::path::Path::new(&(SYSROOT_LOWERED))), &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(_error) => { return None; },
    };
    host.use_entry(&entry);
    Some(rust)
}

pub async fn sysroot_lowered_put<H: SysrootHost>(root: &std::path::Path, cached: bool, key: Option<&str>, rust: &str, host: &H) {
    let at = match key { Some(__nikaia_value) => __nikaia_value, None => return };
    if !cached { return; }
    let entry = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(at)));
    match fs::create_dir(&entry, &fs::Root::Anywhere, true) {
        Ok(_) => {},
        Err(_error) => { return; },
    };
    let partial = host.unique_beside(&nikaia_std::fs::path::join(&(entry), std::path::Path::new(&(SYSROOT_LOWERED))));
    if sysroot_written(&partial, &nikaia_std::fs::path::join(&(entry), std::path::Path::new(&(SYSROOT_LOWERED))), rust).await {
        host.use_entry(&entry);
        return;
    }
    match fs::remove(&partial, &fs::Root::Anywhere, false) {
        Ok(_) => {},
        Err(_error) => { return; },
    };
}

pub(crate) async fn sysroot_written(partial: &std::path::Path, whole: &std::path::Path, rust: &str) -> bool {
    match fs::write(partial, &fs::Root::Anywhere, rust, false, true).await {
        Ok(_) => {},
        Err(_error) => { return false; },
    };
    match fs::rename(partial, whole, &fs::Root::Anywhere) {
        Ok(_) => {},
        Err(_error) => { return false; },
    };
    true
}

